use openvector::{palette::CoreSession,image_document::{DocumentSource,CANCEL_TASK},document_controls::DocumentSettings};
use serde_json::{json,Value};
use std::sync::atomic::Ordering;
fn pixels()->Vec<u8>{vec![0,0,0,255,255,255,255,255,0,0,0,255,255,255,255,255]}
fn controls()->Value{let mut v=Value::Object(DocumentSettings{advanced:true,anti_alias:false,category:2,quality:0,..Default::default()}.to_json());v["lower"]=json!(2);v["upper"]=json!(2);v}
#[test]
fn source_validation_is_transactional_and_reset_retains_controls(){let session=CoreSession::default();let mut doc=session.create_document();doc.set_source(2,2,&pixels(),true,0.0).unwrap();doc.commit_settings(&controls()).unwrap();let before=doc.snapshot().to_json();assert!(doc.set_source(2,2,&[0],true,0.0).is_err());assert_eq!(doc.snapshot().to_json(),before);assert!(doc.set_source(2,2,&pixels(),true,0.5).is_err());assert_eq!(doc.snapshot().to_json(),before);doc.reset();let state=doc.snapshot();assert_eq!(state.original.width,0);assert!(state.settings.advanced);assert_eq!(state.classification.category,-1);assert_eq!(session.random_state(),1);}
#[test]
fn palette_scheduler_hit_keeps_cancellation_and_live_map(){let mut doc=CoreSession::default().create_document();doc.set_source(2,2,&pixels(),true,0.0).unwrap();let mut input=controls();let first=doc.run_task("palette",&input,None).unwrap();assert!(first.did_work);doc.request_cancel();input["complexity"]=json!(7);let second=doc.run_task("palette",&input,None).unwrap();assert!(!second.did_work);assert!(second.state.cancelled);assert_eq!(second.state.settings.complexity,7);assert_eq!(first.state.parameters,second.state.parameters);assert_eq!(first.state.random_state,second.state.random_state);assert_eq!(first.state.segmentation,second.state.segmentation);let direct=doc.analyze(&input,None).unwrap();assert!(!direct.cancelled);assert_eq!(direct.progress,100);}
#[test]
fn interrupted_palette_keeps_candidate_and_random_mutations(){let mut doc=CoreSession::default().create_document();doc.set_source(2,2,&pixels(),true,0.0).unwrap();let handle=doc.cancellation_handle();let mut calls=0;let result=doc.run_task("palette",&controls(),Some(&mut|event,state|{calls+=1;assert_eq!(event.stage,"palette");assert!(state.segmentation.is_some());handle.store(true,Ordering::Relaxed);Ok(())}));assert_eq!(result.unwrap_err(),CANCEL_TASK);assert_eq!(calls,1);let state=doc.snapshot();assert_eq!(state.completed[2],0);assert!(state.cancelled);assert!(state.segmentation.unwrap().indices.is_none());}
#[test]
fn load_cancellation_survives_success_and_failed_load_clears_source(){let mut doc=CoreSession::default().create_document();let handle=doc.cancellation_handle();doc.run_batch_load(&json!({}),||{handle.store(true,Ordering::Relaxed);Ok(DocumentSource{width:2,height:2,bgra:pixels(),has_alpha:true,shadow_control:0.0})}).unwrap();assert!(doc.snapshot().cancelled);assert_eq!(doc.state().original.width,2);doc.cancel_load();assert_eq!(doc.state().original.width,0);assert!(!doc.snapshot().cancelled);let error=doc.run_batch_load(&json!({}),||Err("file unavailable".into())).unwrap_err();assert_eq!(error,"file unavailable");assert_eq!(doc.state().status,1);assert_eq!(doc.state().original.width,0);}
#[test]
fn source_alpha_type_uses_original_not_background_composition(){let mut doc=CoreSession::default().create_document();let mut bgra=pixels();bgra[3]=0;doc.set_source(2,2,&bgra,true,0.0).unwrap();assert_eq!(doc.source_alpha_type(),1);bgra[7]=128;doc.set_source(2,2,&bgra,true,0.0).unwrap();assert_eq!(doc.source_alpha_type(),2);doc.reset();assert_eq!(doc.source_alpha_type(),0);}
